SELECT COUNT(DISTINCT callsign) as unique_flights_online
FROM flights 
WHERE last_updated >= NOW() - INTERVAL '5 minutes';

SELECT COUNT(DISTINCT callsign) as unique_controllers_online
FROM controllers 
WHERE last_updated >= NOW() - INTERVAL '30 minutes';

SELECT COUNT(DISTINCT callsign) as unique_flights_online
FROM flights 
WHERE last_updated >= NOW() - INTERVAL '5 minutes';

SELECT EXTRACT(EPOCH FROM (NOW() - GREATEST(
  COALESCE((SELECT MAX(last_updated_api) FROM flights), TIMESTAMPTZ 'epoch'),
  COALESCE((SELECT MAX(last_updated) FROM controllers), TIMESTAMPTZ 'epoch'),
  COALESCE((SELECT MAX("timestamp") FROM transceivers), TIMESTAMPTZ 'epoch')
)))::BIGINT AS global_lag_seconds;

SELECT (
  EXTRACT(EPOCH FROM (NOW() - GREATEST(
    COALESCE((SELECT MAX(last_updated_api) FROM flights), TIMESTAMPTZ 'epoch'),
    COALESCE((SELECT MAX(last_updated) FROM controllers), TIMESTAMPTZ 'epoch'),
    COALESCE((SELECT MAX("timestamp") FROM transceivers), TIMESTAMPTZ 'epoch')
  ))) / 60
)::BIGINT AS global_lag_minutes;

SELECT ROUND(
  EXTRACT(EPOCH FROM (NOW() - COALESCE((SELECT MAX(last_updated) FROM controllers), TIMESTAMPTZ 'epoch')))
  / 60.0, 1
) AS controllers_lag_minutes;

SELECT COALESCE(
  ROUND(EXTRACT(EPOCH FROM (NOW() - MIN(entry_timestamp)))/60.0, 0),
  0
) AS oldest_open_age_minutes
FROM flight_sector_occupancy
WHERE exit_timestamp IS NULL;
